"""Individually reviewed final 54 LEP units, preserving prior authored fields."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'pending-existing.json').read_text())[55:];expected={r['unit']['unit_key']:r for r in old};rows={}
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
HEALTH='https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10216.htm'
D8858='https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/decreto/d8858.htm'
T931='https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&tipo_pesquisa=T&cod_tema_inicial=931&cod_tema_final=931'
STFMULTA='https://noticias.stf.jus.br/postsnoticias/supremo-permite-fim-de-processo-de-condenado-que-cumpriu-pena-de-prisao-e-nao-tem-condicoes-de-pagar-multa/'
STFALG='https://noticias.stf.jus.br/postsnoticias/stf-nega-pedidos-que-apontavam-descumprimento-de-sumula-que-limita-uso-de-algemas/'
STFDEP='https://noticias.stf.jus.br/postsnoticias/prisao-civil-de-depositario-infiel-e-progressao-de-regime-em-crime-hediondo-sao-tema-de-duas-novas-sumulas-vinculantes/'
SUM527='https://processo.stj.jus.br/SCON/sumstj/doc.jsp?b=SUMU&i=1&l=10&p=false&sumula=527+INPATH%28NUM%29'
def add(n,case,var,q1,q2,**patch):
 k='art-'+str(n);e=copy.deepcopy(expected[k]['explanation']);r={f:e[f] for f in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']};r.update(exemplo=case+' Variação: '+var,prova=[q1,q2]);r['atencao']+=patch.pop('notes',[]);r['pontos']+=patch.pop('extra_points',[]);r['remissoes']=list(dict.fromkeys([LEP,*r['remissoes'],*patch.pop('sources',[])]));r.update(patch)
 if not r['termos']:r['termos']=[dict(termo='Regra do art. '+str(n),significado=r['simples'])]
 rows[k]=r
add(150,'Entidade comunica ausência antes de fechar relatório mensal. Resposta: comunicação a qualquer tempo e relatório mensal coexistem.', 'Não esperar seis meses para comunicar descumprimento só porque o relatório é periódico.', 'O relatório mensal impede informar falta antes do mês terminar? Não. O artigo prevê comunicação A QUALQUER TEMPO sobre ausência/falta, além do relatório mensal.', 'A entidade pode converter a pena apenas por relatar ausência? Não. Comunicação subsidia juízo competente; não é decisão judicial substitutiva.',notes=['Não equiparar qualquer ausência a falta injustificada sem apuração.'])
add(151,'Condenado é intimado de local/dias/horários e comparece pela primeira vez. Resposta: início da execução da limitação no marco do comparecimento.', 'Data da sentença e primeiro comparecimento são fatos distintos.', 'A execução do capítulo começa necessariamente na assinatura da sentença? Não. O parágrafo indica PRIMEIRO COMPARECIMENTO, sem dispensar condições judiciais de execução.', 'Pode exigir presença sem cientificar local, dias e horário no recorte? Não. Cabe ao juiz determinar intimação com essas informações.')
add(152,'Juiz determina comparecimento do agressor a programa de recuperação no caso de violência contra criança. Resposta: parágrafo não é exclusivo de violência contra mulher.', 'O caput permite atividades educativas; não torna todo curso da unidade automaticamente obrigatório sem fundamento.', 'O parágrafo só trata de mulher adulta? Não. Redação da Lei 14.344/2022 também abrange criança/adolescente e os contextos de violência/tratamento descritos.', 'A possibilidade de o juiz determinar significa livre escolha do agressor depois da ordem válida? Não. A decisão pode tornar o comparecimento OBRIGATÓRIO no recorte, não mera recomendação.')
add(153,'Estabelecimento envia relatório mensal e comunica falta fora desse calendário. Resposta: obrigações de fiscalização do cumprimento.', 'Comunicar fato não prova por si ausência injustificada ou autoriza condenação automática.', 'É suficiente um relatório semestral por conter muitos dados? Não. O artigo exige MENSALMENTE, além de comunicação a qualquer tempo dos fatos relevantes.', 'A comunicação substitui toda defesa no incidente? Não. Informação e apuração/decisão são etapas distintas, com garantias pertinentes.')
add(154,'Autoridade recebe ofício da interdição do CP 47,I. Resposta: baixar ato em vinte e quatro horas do RECEBIMENTO, marco do início nesse recorte.', 'Não contar essas vinte e quatro horas da prática do crime nem aplicar indiferentemente a todo inciso do CP 47.', 'O prazo começa da sentença mesmo antes de recebido o ofício? Não. §1º fixa RECEBIMENTO DO OFÍCIO, com ato a partir do qual se inicia execução.', 'As interdições dos incisos II/III seguem apenas o mesmo ato do inciso I? Não. §2º tem determinação judicial de apreensão dos documentos, com objeto específico.',sources=[CP])
add(155,'Pessoa prejudicada comunica descumprimento da interdição ao juízo. Resposta: parágrafo admite essa iniciativa.', 'Comunicante não ganha competência para punir ou impor prisão por conta própria.', 'Somente autoridade pode informar o descumprimento? Não. Qualquer PREJUDICADO pode fazer comunicação, além do dever imediato da autoridade.', 'Toda notícia recebida dispensa verificar fato e ouvir defesa pertinente? Não. A comunicação inicia exame, sem presumir culpa ou sanção automática.')
add(156,'Pena de dezoito meses é analisada para sursis, com requisitos do CP 77. Resposta: teto e período ordinários não bastam sozinhos.', 'CP 77,§2º, tem modalidade etária/humanitária com limites próprios, não negada pelo resumo do art. 156.', 'Toda pena inferior a dois anos tem sursis automaticamente? Não. É preciso atender requisitos do CP 77 e demais regras, incluindo análise da substituição cabível.', 'Dois a quatro anos é a única faixa possível em toda modalidade? Não. CP 77,§2º, contempla regime etário/humanitário, com pena até quatro e prova de quatro a seis anos.',sources=[CP],notes=['Suspensão da PENA não é suspensão do PROCESSO do art. 89 da Lei 9.099; não misturar os institutos.'])
add(157,'Sentença concede ou nega sursis com fundamentos. Resposta: motivação exigida em ambos os sentidos no recorte.', 'Omissão de motivo não é suprida pela afirmação abstrata de que o crime é grave.', 'A negativa pode ser imotivada porque o benefício é facultativo? Não. O artigo exige pronunciamento MOTIVADO tanto para conceder quanto para negar.', 'É a direção prisional que decide sursis da sentença? Não. O texto atribui pronunciamento ao juiz ou tribunal na situação descrita.')
add(158,'Condições são fixadas e prazo começa na audiência do 160. Resposta: não contar automaticamente da assinatura da sentença.', 'Sursis especial do CP 78,§2º, excepciona prestação de serviço/limitação, com condições cumulativas próprias.', 'Todo sursis sempre inclui serviço comunitário sem exceção? Não. §1º ressalva CP 78,§2º; a modalidade especial exige análise própria.', 'O juiz pode mudar condições sem ouvir condenado pelo §2º? Não. A norma admite mudança motivada no recorte, OUVIDO O CONDENADO.',simples='Concedido sursis, juiz fixa condições adequadas ao fato e à pessoa; prazo começa na audiência do 160. Serviço à comunidade ou limitação de fim de semana têm ressalva do CP 78,§2º, para modalidade especial. Modificação das condições exige ouvir condenado. Entidades fiscalizam e comunicam fatos relevantes; mudança autorizada de residência exige comunicação e apresentação imediata no novo local.',sources=[CP])
add(159,'Tribunal concede sursis e confere ao juízo de execução fixar condições/realizar audiência. Resposta: faculdade prevista no §2º.', 'Não confundir regra de fixação pelo tribunal e possibilidade de atribuição ao juízo.', 'O tribunal é obrigado a realizar pessoalmente toda audiência admonitória? Não. §2º permite conferir ao juízo de execução a realização e, no recorte, fixação de condições.', 'A possibilidade significa que qualquer servidor pode inventar condições? Não. São atribuições judiciais reguladas, não delegação administrativa irrestrita.',atencao=['§2º: PODERÁ conferir incumbências ao juízo; não afirmar que toda audiência é necessariamente realizada pelo tribunal ou por regra automática única.'])
add(160,'Após trânsito, juiz lê sentença e adverte condenado das consequências. Resposta: audiência admonitória marca ciência das condições.', 'Não tratar condenação como revogada só por existir notícia posterior sem procedimento.', 'A audiência serve para condenar novamente pelo mesmo fato? Não. Tem função de leitura/advertência e início do regime pertinente, distinta de novo julgamento.', 'O artigo permite omitir advertência sobre descumprimento? Não. Indica expressamente consequências de nova infração e de descumprir condições.')
add(161,'Réu validamente intimado não comparece SEM JUSTIFICATIVA à audiência. Resposta: a ausência injustificada integra a perda de efeito do sursis.', 'Falha da intimação ou impedimento justificado não são a mesma hipótese.', 'Toda ausência, inclusive devidamente justificada, faz perder benefício por esse artigo? Não. A norma exige ausência INJUSTIFICADA após intimação pertinente.', 'O edital textual tem prazo de dez dias? Não. A hipótese de intimação por edital prevê VINTE dias, distinta de outros prazos da execução.')
add(162,'Condenação definitiva por crime doloso no período provoca análise da revogação obrigatória do CP 81. Resposta: distinguir da facultativa.', 'Condenação por culpa/contravenção ou outras condições tem hipóteses próprias; falta de recursos não equivale a frustrar execução sendo solvente.', 'Todo descumprimento tem idêntica consequência obrigatória? Não. CP 81 distingue caput,§1º e prorrogações, com requisitos diferentes.', 'Estar sendo processado por crime no período equivale a condenação definitiva imediata? Não. §2º prevê prorrogação até julgamento, distinta da revogação por condenação irrecorrível.',sources=[CP])
add(163,'Registro do sursis recebe averbação da extinção e permanece sigiloso, com exceções do §2º. Resposta: registro não é certificado público irrestrito.', 'Sigilo não impede toda requisição judicial/MP para instruir processo penal.', 'A extinção permite deixar o registro sem averbação? Não. §1º manda averbar revogação ou extinção, mantendo informação correta.', 'Qualquer empregador recebe o conteúdo automaticamente por pedir? Não. O artigo conserva sigilo e recorte de requisição judicial/MP para processo penal.')
add(164,'MP requer execução da multa com certidão definitiva e citação para dez dias. Resposta: multa permanece sanção penal e exige procedimento próprio.', 'Inadimplemento por pobreza não autoriza converter dívida em prisão; Tema 931 e ADI 7032 têm parâmetros de extinção.', 'A multa virou pena de prisão automática por atraso? Não. CP 51 a trata como dívida de valor executada perante juízo penal, sem restaurar conversão revogada.', 'É sempre impossível extinguir punibilidade com multa não paga após cumprir pena? Não. Tema 931/STJ e ADI 7032/STF exigem examinar impossibilidade econômica e decisão pertinente.',notes=['Competência e legitimidade devem ser integradas ao CP 51 atual; não ensinar cobrança civil isolada como regime universal.','Tema 931: hipossuficiência alegada, salvo decisão concretamente motivada indicando possibilidade; STF ADI 7032 reconhece hipótese de impossibilidade. Não tratar textos como dispensa universal de análise judicial.'],sources=[CP,T931,STFMULTA])
add(165,'Penhora de imóvel é examinada na execução da multa. Resposta: referência ao cível no texto antigo deve ser integrada ao CP 51 atual.', 'Não deslocar automaticamente toda cobrança penal ao cível só porque o bem é imóvel.', 'A frase do 165 isolada prova competência cível atual exclusiva para toda multa? Não. CP 51 vigente prevê execução perante juiz da execução penal; interpretar a remissão histórica nesse quadro.', 'Integrar o regime atual permite executar sem título ou sem defesa? Não. Competência e garantias/título são requisitos distintos, ambos necessários.',simples='O texto do 165 conserva remessa ao Juízo Cível quando a penhora recai em imóvel. Não ler isoladamente como regra atual universal: CP 51, na redação da Lei 13.964/2019, prevê execução da multa perante juiz da execução penal, com normas da dívida de valor. Procedimento e remissões históricas exigem integração; não ensinar transferência automática apenas pelo tipo de bem.',atencao=['Texto residual não substitui CP 51 vigente ou decisões competentes.','Não certificadas todas as controvérsias de competência e atos de expropriação; exemplos não ensinam remessa automática.'],sources=[CP])
add(166,'Penhora de veículo segue regras processuais civis pertinentes à execução penal da multa. Resposta: técnica processual não equivale a mudar toda competência.', 'O texto residual do 165 não deve ser usado como fórmula exclusiva imóvel/cível, móvel/penal sem integração.', 'Aplicar norma processual civil torna necessariamente cível a competência de toda cobrança? Não. CP 51 fixa quadro penal; técnica processual e competência são questões distintas.', 'O artigo permite dispensar defesa de quem sofre penhora? Não. Remissão procedimental preserva garantias e requisitos da execução pertinente.',simples='Para penhora de outros bens, há remissão ao 164,§2º, e às normas processuais civis. Integre competência atual do CP 51: aplicar técnica de execução não significa transferir toda multa ao juízo cível. Não criar exercício binário baseado somente no imóvel/móvel dos textos antigos.',sources=[CP])
add(167,'Doença mental superveniente é reconhecida no recorte de execução da multa. Resposta: suspensão prevista, não extinção automática.', 'Diagnóstico e capacidade precisam de exame; não eliminar multa de toda pessoa com transtorno por estereótipo.', 'A suspensão equivale à extinção definitiva da sanção em todo caso? Não. O artigo remete à SUSPENSÃO do CP 52, distinta de extinção e de tratamento penal discriminatório.', 'A regra descreve doença anterior como único caso possível? Não. Fala SUPERVENIENTE ao condenado; aplicar conforme situação demonstrada e garantias.',sources=[CP,HEALTH])
add(168,'Remuneração de R$ 2.000 teria faixa textual de R$ 200 a R$ 500 para desconto. Resposta: integrar também recursos indispensáveis ao sustento do CP 50,§2º.', 'Não impor R$ 500 automaticamente se compromete sustento protegido, nem presumir desconto de metade do salário.', 'O teto textual permite metade da remuneração? Não. É UM QUARTO, com mínimo de um décimo no recorte e integração das garantias de subsistência.', 'A faixa dispensa ordem judicial ou permite afetar livremente sustento da família? Não. Exige ordem e integração ao CP 50,§2º, que protege recursos indispensáveis.',sources=[CP],notes=['Exemplo aritmético não é ordem real de desconto; hipóteses de cabimento do CP 50,§1º, precisam estar presentes.'])
add(169,'Condenado requer parcelamento no prazo pertinente e juiz verifica renda, ouvido MP. Resposta: prestações mensais, iguais e sucessivas.', 'Melhora financeira/impontualidade demandam exame legal; não prender por dívida nem presumir capacidade só por atraso.', 'O artigo garante parcelamento de qualquer forma escolhida unilateralmente? Não. Há requerimento, situação econômica e decisão judicial com MP.', 'Revogar parcelamento converte automaticamente multa em prisão? Não. Retoma execução da multa no regime vigente, sem restaurar conversão em prisão por dívida.',sources=[CP])
add(170,'Pena privativa termina e multa continua sem quitação. Resposta: analisar cobrança e parâmetros de extinção por impossibilidade, não regra absoluta.', 'Condenado com capacidade concreta não recebe isenção universal apenas porque cumpriu prisão.', 'A pendência da multa sempre impede extinção, mesmo na hipossuficiência reconhecida? Não. Tema 931 e ADI 7032 exigem exame econômico e decisão pertinente.', 'A extinção da pena de prisão apaga automaticamente toda multa em qualquer situação? Não. São sanções distintas; eventual consequência depende do regime e decisão competente.',atencao=['Integrar CP 51 e Tema 931/STJ, não exercício absoluto de pagar sempre ou nunca.','STF ADI 7032: impossibilidade de pagamento inclusive parcelado; notícia não certifica toda jurisprudência posterior.'],sources=[CP,T931,STFMULTA])
add(171,'Após trânsito da sentença de medida de segurança, é ordenada guia executória. Resposta: formalidade própria da execução da medida.', 'Internação clínica de saúde fora de execução penal e medida cautelar têm títulos e requisitos próprios.', 'Toda internação hospitalar civil depende dessa guia de execução penal? Não. O artigo descreve medida de segurança da sentença, distinto de todo atendimento de saúde.', 'Diagnóstico isolado substitui sentença e guia da medida? Não. Execução penal precisa de título e formalidades, além do cuidado juridicamente adequado.',sources=[HEALTH])
add(172,'Medida de segurança ambulatorial é executada com guia judicial. Resposta: requisito alcança ambulatório e internação no seu recorte.', 'Não impedir assistência médica ordinária por ausência de guia penal quando não há execução de medida.', 'Guia é exigida só na internação, dispensada para toda execução ambulatorial? Não. O artigo inclui ambas as modalidades de cumprimento de medida.', 'A regra proíbe todo atendimento de urgência sem guia penal? Não. O recorte é execução da medida, distinto de assistência de saúde por título próprio.',sources=[HEALTH])
add(173,'Guia informa término do prazo mínimo e recebe retificações. Resposta: prazo mínimo não autoriza medida penal perpétua.', 'Súmula 527 limita duração ao máximo da pena abstrata no seu âmbito; não confundir avaliação mínima e teto aplicável.', 'Mencionar prazo mínimo significa inexistência de qualquer limite máximo? Não. Integrar CP, Constituição e Súmula 527, respeitando modalidade e regime da medida.', 'Mudança do prazo permite conservar guia antiga sem atualização? Não. §2º manda retificar e §1º dar ciência ao MP conforme recorte.',sources=[CP,SUM527],notes=['Não estender sem exame o mesmo cálculo a toda conversão de pena em medida; há distinções próprias.'])
add(174,'Exames dos arts. 8º/9º são integrados à medida NO QUE COUBER. Resposta: remissão limitada à compatibilidade.', 'Não importar automaticamente todas as exigências de progressão carcerária para qualquer cuidado de saúde.', 'A expressão no que couber permite aplicar toda regra sem adaptação? Não. Exige pertinência ao regime da medida, com direitos e cuidado individualizado.', 'Ela exclui por completo qualquer exame técnico? Não. O artigo admite aplicação compatível dos exames, distinta de dispensá-los universalmente.',sources=[HEALTH])
add(175,'Relatório com laudo é enviado antes de terminar prazo mínimo; manifestações têm três dias cada e decisão cinco no rito. Resposta: avaliação e prazos próprios.', 'Diligência adicional não autoriza manter medida indefinidamente ou ultrapassar teto só por demora.', 'O prazo de três dias é único e conjunto para MP e defesa? Não. Inciso III prevê SUCESSIVAMENTE três dias para CADA UM.', 'Novas diligências autorizam medida perpétua mesmo após limite aplicável? Não. Integrar limites e Súmula 527; rito de avaliação não revoga garantias temporais.',sources=[SUM527,HEALTH],notes=['Relatório até um mês antes do mínimo; três dias cada; decisão cinco após etapas pertinentes. Não reduzir tudo a um só prazo.'])
add(176,'Defensor fundamenta pedido de exame antes do mínimo. Resposta: art. 176 permite exame em qualquer tempo no recorte.', 'Não afirmar que o mínimo torna impossível toda avaliação antecipada favorável ao paciente.', 'O juiz só pode ordenar exame após cumprir todo prazo mínimo? Não. O artigo permite ainda NO DECORRER do mínimo, mediante requerimento fundamentado dos legitimados.', 'Pedido sem fundamento garante liberação automática? Não. A regra permite exame, com avaliação/procedimento, não benefício incondicional.',sources=[HEALTH])
add(177,'Novo exame é realizado para avaliar cessação. Resposta: aplicar o procedimento anterior no que pertinente.', 'Repetir avaliação não é renovar infinitamente a medida sem controle ou limite.', 'Exames sucessivos afastam todos os limites temporais? Não. São avaliações submetidas ao quadro legal/constitucional e limites, não reinício perpétuo.', 'O artigo inventa rito inteiramente diferente em cada exame? Não. Remete ao anterior NO QUE APLICÁVEL, com adaptações pertinentes.',sources=[SUM527,HEALTH])
add(178,'Desinternação/liberação recebe condições compatíveis dos arts. 132/133. Resposta: integrar CP 97,§3º, e continuidade de cuidado.', 'Não chamar desinternação de livramento penal idêntico em todos os efeitos nem usar condição para internar automaticamente sem necessidade.', 'A remissão faz desaparecer direitos de saúde? Não. Condições precisam ser compatíveis e integradas ao regime da medida e Lei 10.216.', 'A liberação dispensa necessariamente toda condição por não ser pena? Não. O artigo remete às condições pertinentes, com quadro próprio e controle.',sources=[CP,HEALTH])
add(179,'Decisão de liberação definitiva enseja ordem judicial. Resposta: formalidade não deve virar argumento universal para custódia desnecessária.', 'Medida urgente ou cessação de fundamento requer exame competente; não manter pessoa indefinidamente apenas por formalidade isolada.', 'O texto autoriza direção decidir sozinha manter medida perpétua? Não. A ordem e o controle são judiciais, integrados aos limites e direitos aplicáveis.', 'Toda decisão de cuidado/liberdade deve ser retardada por fórmula literal isolada? Não. Confrontar título, recursos, urgência e quadro constitucional; este artigo não certifica todas as situações.',sources=[HEALTH],notes=['Não certificada toda jurisprudência de liberação provisória/urgente; sem exercício automático de retenção até trânsito em qualquer caso.'])
add(180,'Pena de dois anos no aberto já teve seis meses cumpridos e recomendação examinada. Resposta: atende recortes quantitativos, sem concessão automática.', 'Substituição na sentença do CP 44 tem requisitos distintos da conversão executória deste artigo.', 'Qualquer cumprimento de um quarto garante conversão mesmo no fechado? Não. O artigo exige também aberto, pena até dois anos e recomendação dos critérios indicados.', 'O artigo revoga todos os requisitos da substituição inicial do CP 44? Não. Trata de conversão durante execução, distinto da decisão originária da sentença.',sources=[CP])
add(181,'Descumprimento injustificado de serviço é apurado antes de decidir conversão. Resposta: integrar CP 44,§§4º/5º, vigente e garantias.', 'Impossibilidade justificada ou nova pena compatível exige análise, não conversão automática irrestrita.', 'A remissão antiga ao CP 45 continua descrevendo corretamente toda conversão? Não. CP vigente tem disciplina no 44,§§4º/5º; confrontar atualização antes de aplicar.', 'Nova condenação sempre exige conversão sem analisar possibilidade de cumprimento simultâneo? Não. CP 44,§5º, prevê decisão da execução e possibilidade de manter se compatível.',simples='O artigo enumera hipóteses de conversão de restritivas, mas caput conserva remissão antiga ao CP 45. Integre CP 44,§§4º/5º, atual: descumprimento injustificado, decisão competente e análise de nova condenação/compatibilidade. Não converter automaticamente por impedimento justificado nem ignorar crédito de cumprimento e regras atuais.',atencao=['Corrigida explicação antiga que copiava CP 45 como regime atual da conversão.','Defesa, justificativa e decisão necessária; não prisão automática por qualquer comunicação.'],sources=[CP])
add(183,'Transtorno superveniente leva a pedido fundamentado da Defensoria para substituição por medida. Resposta: faculdade judicial com avaliação.', 'Doença não elimina automaticamente condenação anterior nem autoriza ampliar execução indefinidamente.', 'Todo diagnóstico impõe substituição automática pelo diretor? Não. O artigo diz juiz PODERÁ, com elementos e integração ao regime de saúde e da medida.', 'A Defensoria está excluída dos legitimados? Não. Lei 12.313/2010 a incluiu expressamente, além dos legitimados do artigo.',notes=['Conversão do 183 tem limites próprios; não aplicar duração perpétua nem confundir com absolvição imprópria inicial.','Não certificadas todas as políticas locais/CNJ, sem ensino de internação automática por diagnóstico.'],sources=[HEALTH,CP])
add(184,'Incompatibilidade com tratamento ambulatorial é examinada tecnicamente. Resposta: eventual internação precisa ser adequada e necessária.', 'Ausência de rede ou simples pobreza não justificam automaticamente transformar cuidado em internação asilar.', 'O prazo mínimo de um ano impede qualquer exame antecipado do 176? Não. Integrar o procedimento e limites; mínimo textual não proíbe avaliação antecipada compatível.', 'Uma dificuldade de comparecimento basta sempre para internação automática? Não. Examinar causas, recursos extra-hospitalares, necessidade clínica e decisão no regime da Lei 10.216.',sources=[HEALTH,SUM527],notes=['Não perpetuar custódia por ausência de rede social; Lei 10.216 exige insuficiência de recursos extra-hospitalares para internação.'])
add(185,'Cálculo conserva pessoa presa além do limite devido. Resposta: suscitar excesso/desvio, com conferência do título e créditos.', 'Incidente não se restringe à prisão: atos além de normas e sentença têm recorte próprio.', 'Apenas ultrapassar o tempo de prisão pode ser examinado? Não. O texto alcança atos além dos limites da sentença e normas legais/regulamentares.', 'Uma reclamação por conveniência prova sozinha excesso? Não. É preciso examinar ato e limites aplicáveis, com decisão competente.')
add(186,'Sentenciado suscita excesso por erro de cálculo. Resposta: legitimidade própria, sem monopólio do MP.', 'Representar pedido não significa que o próprio sentenciado possa alterar sozinho o cálculo oficial.', 'Somente o MP pode suscitar o incidente? Não. Rol inclui Conselho, sentenciado e demais órgãos da execução.', 'A Defensoria fica necessariamente excluída por não constar num inciso nominal? Não. Integre órgãos da execução do 61 e atribuições próprias, sem restringir defesa por leitura isolada.')
add(187,'Anistia concedida no regime competente enseja declaração judicial de extinção. Resposta: concessão e aplicação judicial são funções distintas.', 'Não confundir anistia legislativa e indulto presidencial; pedido de anistia não equivale à sua existência.', 'O juiz concede livremente anistia só por este artigo? Não. O dispositivo começa CONCEDIDA A ANISTIA e regula declaração da consequência, não competência legislativa substitutiva.', 'Somente o preso pode provocar declaração? Não. Há iniciativa judicial e legitimados/propostas enumerados, no recorte.',sources=[CF])
add(188,'Condenado pede indulto individual; pedido segue procedimento, sem garantia de concessão. Resposta: iniciativa e decisão são etapas diferentes.', 'Não tratar essa petição como indulto coletivo automaticamente aplicável a todos.', 'Petição do condenado é excluída dos meios de provocação? Não. Está expressamente prevista, além das iniciativas do MP, Conselho e administração.', 'A iniciativa do diretor já extingue a pena por si? Não. Provoca pedido, distinto de concessão e aplicação judicial.')
add(189,'Pedido individual com documentos vai ao Conselho para parecer e Ministério da Justiça. Resposta: itinerário do dispositivo.', 'Indulto coletivo por decreto tem aplicação própria do 193, não idêntica tramitação de toda petição individual.', 'Parecer favorável do Conselho já vale como decreto de indulto? Não. É etapa preparatória com encaminhamento, distinta da concessão pela autoridade competente.', 'Toda aplicação de indulto coletivo precisa repetir essa petição individual? Não. O 193 tem procedimento próprio de aplicação pelo juízo competente.')
add(190,'Conselho reúne dados, diligencia e emite parecer. Resposta: parecer técnico/administrativo não é sentença de extinção.', 'Prontuário incompleto pode demandar diligências; não presumir inexistência de requisitos apenas por campo vazio.', 'O Conselho pode diligenciar sobre circunstância omitida? Sim. O artigo prevê diligências necessárias e esclarecimento de formalidades/circunstâncias.', 'O parecer transfere ao Conselho o poder presidencial de conceder indulto? Não. Instrução, parecer e concessão têm competências distintas.')
add(191,'Petição instruída é submetida ao Presidente no rito individual. Resposta: decisão e instrução ministerial se distinguem.', 'Constituição 84,XII, parágrafo único, permite delegação no recorte constitucional; não enunciar competência indelegável absoluta.', 'O ministro concede necessariamente por apenas ter processado pedido? Não. O artigo prevê despacho presidencial; eventual delegação depende de quadro constitucional válido.', 'A Constituição proíbe qualquer delegação da atribuição de indulto? Não. CF 84, parágrafo único, admite delegação do inciso XII aos destinatários previstos, no recorte.',sources=[CF],notes=['Não inventar delegação concreta ou decreto concedente não verificado; exemplo trata do rito textual.'])
add(192,'Decreto de comutação válido permite reduzir pena nos seus termos. Resposta: ajustar execução, não extinguir universalmente toda pena.', 'Indulto e comutação têm requisitos/efeitos do ato; não atribuir retroativamente todos os efeitos sem analisar o decreto.', 'Qualquer comutação equivale a extinção total? Não. O artigo distingue extinção por indulto e ajuste aos termos do decreto na comutação.', 'Basta o candidato citar existência de decreto sem verificar requisitos pessoais? Não. A aplicação exige enquadramento no ato pertinente e decisão competente.')
add(193,'Pessoa preenche decreto coletivo e juiz providencia aplicação de ofício. Resposta: iniciativa não é concessão livre fora do decreto.', 'Súmula 535: falta grave não interrompe prazo para indulto/comutação, mas o decreto pode conter requisitos próprios.', 'É obrigatório novo pedido pessoal em toda aplicação? Não. O artigo admite atuação de ofício e dos legitimados, conforme requisitos.', 'De ofício permite criar indulto que não consta do decreto? Não. Juiz aplica benefício existente no seu âmbito, não substitui competência concedente.',notes=['Não certificada elegibilidade em qualquer decreto anual concreto; exercícios não inventam indulto de 2026.'])
add(194,'Incidente de execução é examinado judicialmente. Resposta: juízo de execução, sem negar atribuições administrativas válidas da LEP.', 'Advertência administrativa e procedimentos internos não se tornam todos competência judicial exclusiva só por esta frase.', 'O artigo elimina todas as competências da administração prisional? Não. Regula procedimento judicial das situações legais, sem revogar atribuições administrativas previstas.', 'A direção pode substituir decisão judicial de remição no incidente? Não. A competência judicial do procedimento precisa ser preservada no recorte pertinente.')
add(195,'Interessado ou familiar legitimado provoca procedimento; juiz também atua no recorte de ofício. Resposta: rol amplo.', 'Iniciar incidente não dispensa contraditório ou fundamento para medidas gravosas.', 'Só advogado pode sempre provocar qualquer procedimento por este artigo? Não. O rol prevê interessado, representantes/familiares, órgãos e iniciativa judicial, integrado à defesa técnica cabível.', 'Iniciativa de ofício permite dispensar manifestação dos afetados em todo caso? Não. A iniciativa e o contraditório são etapas distintas do procedimento.')
add(196,'MP requer medida; o condenado é ouvido em três dias no recorte. Resposta: quem já é requerente não precisa ser ouvido novamente por mera repetição desse artigo.', 'Se prova oral/pericial é indispensável, não tratar decisão de plano como obrigação de decidir sem prova.', 'O texto exige nova oitiva idêntica de quem figura como requerente? Não. A condição é QUANDO NÃO FIGUREM COMO REQUERENTES, integrada ao procedimento.', 'Toda decisão tem de ser de plano mesmo com prova indispensável? Não. §2º prevê produção e decisão após prova ou audiência pertinente.')
add(197,'Defesa interpõe agravo da execução. Resposta: regra legal sem efeito suspensivo automático.', 'Ausência de efeito suspensivo ordinário não prova impossibilidade absoluta de tutela judicial urgente no sistema.', 'O agravo suspende automaticamente a decisão pelo artigo? Não. A regra é SEM EFEITO SUSPENSIVO, distinta de eventual tutela excepcional cabível.', 'O artigo sozinho fixa prazo recursal de trinta dias? Não. Ele não indica esse prazo; consultar disciplina/jurisprudência específica sem inventar prazo.',notes=['Não certificada toda jurisprudência recursal ou tutela excepcional; sem exercício de prazo não verificado.'])
add(198,'Servidor divulga imagem para expor preso à notoriedade indevida ou informação prejudicial à segurança. Resposta: examinar proibição no recorte.', 'Não transformar proteção da pessoa em proibição universal de transparência, fiscalização ou comunicação legítima de irregularidades.', 'Todo dado sobre estabelecimento é segredo absoluto pelo artigo? Não. A descrição tem recortes de segurança/disciplina e notoriedade inconveniente; integrar transparência e direitos.', 'A palavra defesa significa aqui atividade do advogado? Não. É forma de dizer VEDADA, referente à divulgação pelos destinatários do artigo.',atencao=['Corrigido exemplo antigo que afirmava proibição genérica de divulgar rebelião/expor à imprensa sem os recortes.','Não certificada toda jurisprudência sobre comunicação e imagem; não usar artigo como censura universal.'])
add(199,'Preso oferece resistência e uso excepcional de algemas é fundamentado por escrito. Resposta: Decreto 8.858 e SV 11 exigem recortes concretos.', 'Algemar toda pessoa apenas por estar presa ou para exposição midiática não se torna lícito por prática habitual.', 'A condição de preso autoriza algemas obrigatórias em toda situação? Não. Exige resistência, fundado receio de fuga ou perigo à integridade e justificativa escrita no regime pertinente.', 'Parturiente pode ser algemada livremente no trajeto e hospitalização pelo art. 199? Não. Decreto 8.858, art. 3º, veda nas fases enumeradas; integrar CPP e garantias.',extra_points=['Decreto 8.858/2016: resistência, fundado receio de fuga ou perigo; excepcionalidade justificada POR ESCRITO.','Art. 3º: trabalho de parto, trajeto unidade/hospital e pós-parto durante hospitalização.'],sources=[D8858,STFALG],notes=['STF SV 11 não concede liberdade irrestrita ao agente; não certificar toda jurisprudência de nulidade de atos específicos.'])
add(200,'Condenado por crime político não é obrigado ao trabalho pelo artigo. Resposta: exceção, não proibição de atividade voluntária.', 'Rótulo político atribuído por interessado não transforma automaticamente qualquer delito em crime político.', 'A ausência de obrigação equivale a proibição absoluta de trabalhar? Não. O texto dispensa obrigação, distinto de impedir atividade voluntária lícita.', 'Todo crime com repercussão política é enquadrado automaticamente? Não. Qualificação jurídica exige análise; não basta opinião ou rótulo pessoal.')
add(201,'Prisão civil válida por alimentos, sem estabelecimento adequado, demanda separação pertinente. Resposta: regra de local não cria novo título de prisão.', 'A expressão histórica prisão administrativa não autoriza autoridade civil a prender livremente; depósito infiel não tem prisão civil admitida pelo STF.', 'O artigo restaura prisão civil de depositário infiel? Não. STF veda essa prisão em qualquer modalidade; local de cumprimento não cria hipótese válida de custódia.', 'A menção à administrativa autoriza prender sem título constitucional? Não. Integrar CF 5,LXI e garantias; texto residual de local não é autorização geral de prisão administrativa.',simples='Na falta de estabelecimento adequado, texto prevê seção especial da cadeia pública para prisão civil e menciona prisão administrativa. Integre Constituição e jurisprudência: regra de local não cria hipótese/título de custódia. Não restaurar prisão do depositário infiel nem poder administrativo civil irrestrito de prender. Prisão civil por alimentos exige seus próprios pressupostos e separação adequada.',sources=[CF,STFDEP],atencao=['Terminologia histórica não basta para autorizar prisão hoje; examinar fundamento constitucional e decisão competente.'])
add(202,'Após cumprimento/extinção, certidão comum não traz notícia da condenação, ressalvadas hipóteses legais. Resposta: proteção do egresso com exceções.', 'Não apagar todo registro interno nem impedir instrução de nova infração prevista na ressalva.', 'O artigo impõe apagar irreversivelmente todos os dados judiciais? Não. Trata de folha/atestados/certidões e ressalva nova infração/outros casos legais, distinto de eliminar todo registro.', 'Qualquer empregador recebe automaticamente notícia de condenação cumprida? Não. A proteção legal permanece, salvo hipótese expressamente autorizada.')
add(203,'Questão histórica pergunta seis meses da publicação para normas e projetos de implantação. Resposta: marco inicial de 1984.', 'Uma atualização em 2026 não reinicia toda carência nem suspende automaticamente todo financiamento federal por qualquer irregularidade.', 'Cada alteração da LEP reinicia os seis meses do artigo? Não. O marco é publicação original, com hipóteses de ampliação e requisitos próprios.', 'O texto permite cortar qualquer recurso da União por toda falha estadual? Não. §4º refere descumprimento INJUSTIFICADO e ajuda para execução de penas/medidas, não bloqueio universal.',atencao=['Disposição histórica de implantação; não certificar execução orçamentária concreta ou suspensão atual automática.','§3º: Conselho pode ampliar prazo mediante solicitação justificada instruída com projetos, não prorrogação tácita ilimitada.'])
add(204,'Estudo histórico relaciona vigência da LEP à reforma da Parte Geral do CP. Resposta: concomitância, não vigência instantânea pela assinatura.', 'Leis modificadoras têm suas próprias datas; não herdam automaticamente o marco original de 1984.', 'Toda alteração de 2026 começou a valer em 1984 por este artigo? Não. A concomitância é do regime original; modificadoras têm publicação/vacância próprias.', 'A preservação de lei antiga 3.274/1957 em arquivo a torna vigente? Não. Foi especialmente revogada; consulta histórica deve ser ressalvada.')

# Explicitly refine two units published in the preceding batch, keeping CAS evidence.
prior=json.loads((p/'after-03/legal_unit_explanations.json').read_text());units=json.loads((p/'after-03/legal_course_units.json').read_text());byid={e['unit_id']:e for e in prior}
for n in [108,149]:
 key='art-'+str(n);u=next(u for u in units if u['course_id']=='283d9de3-42ff-5074-b70a-bc273bf40d3f' and u['unit_key']==key);expected[key]={'unit':u,'explanation':byid[u['id']]};r={f:copy.deepcopy(byid[u['id']][f]) for f in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 if n==108:r['simples']='Transtorno mental superveniente na execução exige cuidado e avaliação clínica/judicial. A referência textual ao HCTP deve ser integrada à Lei 10.216: internação depende de insuficiência dos recursos extra-hospitalares e não é consequência automática de qualquer diagnóstico. Distinga tratamento e eventual conversão judicial do art. 183.';r['pontos']=['Cuidado individualizado na execução, distinto de capacidade ao tempo do fato.','Internação não automática: integrar necessidade clínica e Lei 10.216.','Art. 183: eventual substituição judicial, com pressupostos próprios.']
 else:r['pontos']=['Entidade credenciada/convencionada designada judicialmente; tarefas gratuitas conforme aptidões.','Texto residual do §1º: oito horas semanais; CP 46 atual calcula uma hora de tarefa por dia de condenação.','Calendário compatível com trabalho e regime aplicável, não oito horas invariáveis.','Início da execução no primeiro comparecimento.']
 r['termos']=[dict(termo='Cuidado individualizado' if n==108 else 'Quantidade e calendário de tarefas',significado='Necessidade clínica e decisão no regime de saúde, sem internação automática por diagnóstico.' if n==108 else 'Uma hora por dia de condenação não equivale a calendário semanal fixo universal.')];rows[key]=r

rows['art-165']['pontos']=['Referência histórica à remessa ao cível confrontada com CP 51 atual.','Não deslocar automaticamente competência penal apenas pelo bem penhorado.']
rows['art-166']['atencao']=['Técnica processual civil e competência jurisdicional não são conceitos idênticos; integrar CP 51.']
rows['art-156']['pontos']=['Sursis ordinário: prova de dois a quatro anos, pena até dois anos e demais requisitos CP 77.','Modalidade etária/humanitária: CP 77,§2º, com limites próprios.','Suspensão da pena é distinta de suspensão condicional do processo.']
rows['art-170']['simples']='Multa cumulativa pode ser cobrada no regime próprio e com limites de desconto. Fim da prisão, livramento ou sursis não apagam universalmente a sanção. Ao examinar extinção com multa não paga, integrar Tema 931/STJ e ADI 7032/STF sobre impossibilidade econômica, com decisão competente; não prisão por dívida nem obstáculo absoluto pela pobreza.'
rows['art-198']['simples']='É VEDADA aos integrantes dos órgãos da execução/servidores a divulgação no recorte de perturbação da segurança/disciplina ou exposição à notoriedade inconveniente. Não é sigilo absoluto de toda informação nem proibição universal de fiscalização, transparência ou comunicação legítima de irregularidades.'
rows['art-203']['simples']='Disposição histórica de implantação: seis meses da publicação original para normas e projetos, com possibilidade de ampliação fundamentada pelo Conselho no §3º. Não reinicia carência em cada atualização de 2026. §4º trata de descumprimento injustificado e ajuda para despesas de execução, sem corte automático de todo recurso federal por qualquer irregularidade.'
for r in rows.values():
 if r['termos'] and r['termos'][0]['termo'].startswith('Regra do art.'):r['termos'][0]['significado']=r['simples']
assert len(rows)==56 and set(rows)==set(expected)
for k,r in rows.items():assert 'Variação:' in r['exemplo'] and len(r['prova'])==2 and all('?' in q and q.split('?',1)[1].strip() for q in r['prova']),k
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'lep','units':rows},ensure_ascii=False,indent=2)+'\n')
